class Solution {
    fun minCost(basket1:IntArray,basket2:IntArray):Long{
        val difference=HashMap<Int,Int>();
        var minimum=Int.MAX_VALUE;
        for(value in basket1){
            difference[value]=(difference[value]?:0)+1;
            minimum=minOf(minimum,value)
        };
        for(value in basket2){
            difference[value]=(difference[value]?:0)-1;
            minimum=minOf(minimum,value)
        };
        val first=mutableListOf<Int>();
        val second=mutableListOf<Int>();
        for((value,count) in difference){
            if(kotlin.math.abs(count)%2==1)return -1;
            repeat(maxOf(0,count/2)){
                first.add(value)
            };
            repeat(maxOf(0,-count/2)){
                second.add(value)
            }
        };
        first.sort();
        second.sortDescending();
        var cost=0L;
        for(i in first.indices)cost+=minOf(first[i].toLong(),second[i].toLong(),2L*minimum);
        return cost
    }
}

